/* Fleet staff (with documents) · trip duty list with crew, kilometres and bata · wage & bata rate card · payroll.
   A duty is one trip of one vehicle: one or two drivers and a cleaner (attender) travel from one place to another.
   Two drivers share the trip at the normal wage; a driver who goes alone is paid the single-driver wage (₹2,400 by default).
   Each duty has a trip sheet: kilometres, diesel, timings, advance, trip expenses and income.
   Collections are prefixed fl_ (fleet and logistics roles, plus the administrator). */
'use strict';

const FL_ROLES = ['Driver', 'Cleaner', 'Office staff', 'Mechanic', 'Supervisor']; // cleaner = attender / conductor
const FL_SOLO_WAGE = 2400;
const FL_EXPENSES = [['pooja', 'Pooja'], ['beta1', 'Driver Beta 1'], ['beta2', 'Driver Beta 2'], ['attBeta', 'Attender Beta'], ['parking', 'Parking'], ['police', 'Police'], ['rto', 'RTO'], ['luggage', 'Luggage'], ['grease', 'Grease'], ['air', 'Air'], ['food', 'Food'], ['other', 'Other']];
const FL_INCOME = [['incCollection', 'Trip collection / hire'], ['incLuggage', 'Luggage income'], ['incOther', 'Other income']];
