      c.L.forEach((l, q) => { l.sheetId = id; l.status = c.closed ? 'Completed' : 'Assigned'; l.rno = (l._bus ? '23' : '41') + pad(l._i + 1) + (q ? 'B' : 'A'); l.load = l._bus ? 'Seats' : 'Parcel'; l.km = l._km; if (c.closed) { l.qty = l._bus ? 38 + (l._i % 6) : 120 + l._i * 7; l.amt = l._bus ? 32000 + l._i * 900 : l._truck ? 26000 : 4200; l.hrs = l._bus ? '09:05' : '10:30'; } });
