  const D = FL.list('sheets').filter(d => d.status !== 'Cancelled' && d.date >= st.from && d.date <= st.to && (!st.veh || d.vehicleId === st.veh)).sort((a, b) => a.date.localeCompare(b.date) || (+a.no || 0) - (+b.no || 0)).map(s => { const legs = flLegs(s.id); const T = flMemoTotals(s, flMemo(s), legs); return { ...s, T, sheet: { dieselL: T.fuelL, dieselAmt: T.fuelAmt, adblue: T.adblueL, advance: T.advance }, legs, trip: flChain(legs) }; });
  const reg = d => FL.veh(d.vehicleId)?.regNo || '', km = d => d.endKm > d.startKm ? d.endKm - d.startKm : 0, dl = d => +d.sheet.dieselL || 0, da = d => +d.sheet.dieselAmt || 0, N = n => (Math.round(n * 100) / 100).toLocaleString('en-IN'), mil = (k, l) => k && l ? (k / l).toFixed(2) : '—', drvIds = d => [...new Set(d.legs.flatMap(l => [l.driverId, l.driver2Id]).filter(Boolean))], drivers = d => drvIds(d).map(FL.name).join(' & ');
  const group = (rows, keyOf) => { const m = new Map(); rows.forEach(d => [].concat(keyOf(d)).forEach(k => { if (!m.has(k)) m.set(k, []); m.get(k).push(d); })); return [...m]; }, sum = (rows, f) => rows.reduce((s, d) => s + (+f(d) || 0), 0), r2 = x => Math.round(x * 100) / 100;
  const fuelled = D.filter(d => km(d) && dl(d)), avgOf = rows => { const f = rows.filter(d => km(d) && dl(d)); return sum(f, dl) ? sum(f, km) / sum(f, dl) : 0; }, rateOf = rows => { const f = rows.filter(d => dl(d) && da(d)); return sum(f, dl) ? sum(f, da) / sum(f, dl) : 0; };
  const vehAvg = Object.fromEntries(group(fuelled, d => d.vehicleId).map(([id, r]) => [id, avgOf(r)])), low = d => km(d) && dl(d) && vehAvg[d.vehicleId] && r2(km(d) / dl(d)) < vehAvg[d.vehicleId] * 0.9;
